insert into public.posts (id, board_id, author_id, autor_alias, titulo, cuerpo, estado, borrado_por, es_simulado, created_at, updated_at) values
  (1, (select id from public.boards where slug = 'prog'), '00000000-0000-4000-8000-000000000010', 'sim_10', 'Apuntes de árboles binarios (Programación 3)', 'Subo el resumen de la clase: recorridos inorden, preorden y postorden con ejemplos en JavaScript.', 'publicado', null, true, now() - interval '623 hours', now() - interval '623 hours'),
  (2, (select id from public.boards where slug = 'prog'), '00000000-0000-4000-8000-000000000012', 'sim_12', '¿Alguien tiene el TP de bases de datos?', 'Me falta la consigna del trabajo práctico de consultas SQL. ¿Me la pasan por acá?', 'publicado', null, true, now() - interval '207 hours', now() - interval '207 hours'),
  (3, (select id from public.boards where slug = 'prog'), '00000000-0000-4000-8000-000000000011', 'sim_11', 'Error en Vue: Cannot read properties of undefined', 'Me aparece al renderizar una lista antes de que lleguen los datos. ¿Se soluciona con v-if?', 'publicado', null, true, now() - interval '824 hours', now() - interval '824 hours'),
  (4, (select id from public.boards where slug = 'prog'), '00000000-0000-4000-8000-000000000017', 'sim_17', 'Editor recomendado para practicar C++', '¿Qué editor liviano usan en las netbooks de la escuela? El que tengo anda muy lento.', 'publicado', null, true, now() - interval '580 hours', now() - interval '580 hours'),
  (5, (select id from public.boards where slug = 'prog'), '00000000-0000-4000-8000-000000000006', 'sim_06', 'Grupo de estudio para el parcial de algoritmos', 'Armamos un grupo los martes en la biblioteca. Pueden sumarse de cualquier división.', 'publicado', null, true, now() - interval '536 hours', now() - interval '536 hours'),
  (6, (select id from public.boards where slug = 'prog'), '00000000-0000-4000-8000-000000000016', 'sim_16', 'Guía de Git para el proyecto integrador', 'Dejo una guía corta con commit, branch y merge, pensada para trabajar en equipo.', 'borrado', 'autor', true, now() - interval '603 hours', now() - interval '603 hours'),
  (7, (select id from public.boards where slug = 'prog'), '00000000-0000-4000-8000-000000000003', 'sim_03', '¿Cómo conectar un formulario con Supabase?', 'Ya tengo el formulario en Vue y necesito guardar los datos. ¿Por dónde empiezo?', 'publicado', null, true, now() - interval '1151 hours', now() - interval '1151 hours'),
  (8, (select id from public.boards where slug = 'prog'), '00000000-0000-4000-8000-000000000010', 'sim_10', 'Ejercicios resueltos de recursividad', 'Hice la resolución de los ejercicios 1 al 8 de la guía. Revisen si ven errores.', 'publicado', null, true, now() - interval '470 hours', now() - interval '470 hours'),
  (9, (select id from public.boards where slug = 'prog'), '00000000-0000-4000-8000-000000000010', 'sim_10', 'Se cayó la red del laboratorio', 'Desde la primera hora no conecta ninguna máquina del laboratorio 2. ¿Pasa lo mismo en otras aulas?', 'publicado', null, true, now() - interval '1202 hours', now() - interval '1202 hours'),
  (10, (select id from public.boards where slug = 'prog'), '00000000-0000-4000-8000-000000000010', 'sim_10', 'Bibliotecas de gráficos para JavaScript', 'Busco una librería simple para hacer gráficos de barras en la feria de ciencias.', 'publicado', null, true, now() - interval '1071 hours', now() - interval '1071 hours'),
  (11, (select id from public.boards where slug = 'taller'), '00000000-0000-4000-8000-000000000007', 'sim_07', 'Aviso: taller cerrado el jueves', 'Por tareas de mantenimiento el taller no abre el jueves. Se retoma el viernes en el horario habitual.', 'publicado', null, true, now() - interval '877 hours', now() - interval '877 hours'),
  (12, (select id from public.boards where slug = 'taller'), '00000000-0000-4000-8000-000000000014', 'sim_14', 'Se perdió una llave inglesa de 14 mm', 'La dejé en el banco 3 después de la práctica. Si la encuentran avisen por acá.', 'publicado', null, true, now() - interval '1256 hours', now() - interval '1256 hours'),
  (13, (select id from public.boards where slug = 'taller'), '00000000-0000-4000-8000-000000000010', 'sim_10', 'Guía de soldadura con estaño', 'Resumen con temperaturas, tipos de punta y errores comunes. Pensado para primer año de taller.', 'publicado', null, true, now() - interval '912 hours', now() - interval '912 hours'),
  (14, (select id from public.boards where slug = 'taller'), '00000000-0000-4000-8000-000000000015', 'sim_15', '¿Quién tiene el plano del proyecto de tercer año?', 'Necesito la hoja 2 del plano para terminar el soporte. La mía se mojó.', 'publicado', null, true, now() - interval '360 hours', now() - interval '360 hours'),
  (15, (select id from public.boards where slug = 'taller'), '00000000-0000-4000-8000-000000000008', 'sim_08', 'Se necesitan voluntarios para ordenar el pañol', 'Sábado a la mañana. Se entrega certificado de horas solidarias.', 'publicado', null, true, now() - interval '654 hours', now() - interval '654 hours'),
  (16, (select id from public.boards where slug = 'taller'), '00000000-0000-4000-8000-000000000009', 'sim_09', 'Normas de seguridad: lentes obligatorios', 'Recordatorio: no se puede usar ninguna máquina sin lentes y calzado cerrado.', 'borrado', 'autor', true, now() - interval '118 hours', now() - interval '118 hours'),
  (17, (select id from public.boards where slug = 'taller'), '00000000-0000-4000-8000-000000000003', 'sim_03', 'Sobran resistencias de 220 ohm', 'Tengo una bolsa de resistencias de más. Las dejo en el pañol para quien las necesite.', 'publicado', null, true, now() - interval '124 hours', now() - interval '124 hours'),
  (18, (select id from public.boards where slug = 'taller'), '00000000-0000-4000-8000-000000000015', 'sim_15', 'Torno fuera de servicio', 'El torno 2 tiene una falla en el husillo. No usarlo hasta que lo revisen.', 'publicado', null, true, now() - interval '604 hours', now() - interval '604 hours'),
  (19, (select id from public.boards where slug = 'compraventa'), '00000000-0000-4000-8000-000000000017', 'sim_17', 'Vendo calculadora científica', 'Casi sin uso, con funda. Se puede ver en el recreo largo. Consultar precio por acá.', 'publicado', null, true, now() - interval '1124 hours', now() - interval '1124 hours'),
  (20, (select id from public.boards where slug = 'compraventa'), '00000000-0000-4000-8000-000000000006', 'sim_06', 'Compro tester digital', 'Busco un tester usado en buen estado para electrónica. Pago razonable.', 'borrado', 'moderacion', true, now() - interval '732 hours', now() - interval '732 hours'),
  (21, (select id from public.boards where slug = 'compraventa'), '00000000-0000-4000-8000-000000000005', 'sim_05', 'Vendo apuntes encuadernados de Física', 'Tengo los apuntes completos del año pasado, anillados y ordenados por unidad.', 'publicado', null, true, now() - interval '430 hours', now() - interval '430 hours'),
  (22, (select id from public.boards where slug = 'compraventa'), '00000000-0000-4000-8000-000000000019', 'sim_19', 'Vendo placa Arduino con cables', 'Incluye cables y protoboard. La usé en un solo proyecto. Cambio por otra cosa también.', 'borrado', 'moderacion', true, now() - interval '875 hours', now() - interval '875 hours'),
  (23, (select id from public.boards where slug = 'compraventa'), '00000000-0000-4000-8000-000000000015', 'sim_15', 'Busco mochila resistente', 'Que tenga lugar para una netbook de 14 pulgadas. Acepto usada.', 'publicado', null, true, now() - interval '933 hours', now() - interval '933 hours'),
  (24, (select id from public.boards where slug = 'compraventa'), '00000000-0000-4000-8000-000000000009', 'sim_09', 'Vendo guardapolvo talle M', 'Muy buen estado, lavado. Retiro por la escuela.', 'publicado', null, true, now() - interval '406 hours', now() - interval '406 hours'),
  (25, (select id from public.boards where slug = 'compraventa'), '00000000-0000-4000-8000-000000000012', 'sim_12', 'Intercambio libros de matemática', 'Cambio un libro de álgebra por uno de análisis. Misma editorial.', 'publicado', null, true, now() - interval '922 hours', now() - interval '922 hours'),
  (26, (select id from public.boards where slug = 'eventos'), '00000000-0000-4000-8000-000000000019', 'sim_19', 'Muestra de proyectos técnicos: fecha y lugar', 'Se hará en el patio cubierto. Cada curso debe confirmar su stand antes del viernes.', 'publicado', null, true, now() - interval '686 hours', now() - interval '686 hours'),
  (27, (select id from public.boards where slug = 'eventos'), '00000000-0000-4000-8000-000000000018', 'sim_18', 'Torneo de fútbol interdivisión', 'Inscripción por curso en la preceptoría. Los partidos son en los recreos largos.', 'publicado', null, true, now() - interval '436 hours', now() - interval '436 hours'),
  (28, (select id from public.boards where slug = 'eventos'), '00000000-0000-4000-8000-000000000011', 'sim_11', 'Charla de egresados sobre trabajo en tecnología', 'Participan tres egresados de distintas especialidades. Entrada libre.', 'publicado', null, true, now() - interval '236 hours', now() - interval '236 hours'),
  (29, (select id from public.boards where slug = 'eventos'), '00000000-0000-4000-8000-000000000002', 'sim_02', 'Feria de ciencias: inscripción abierta', 'Pueden presentarse proyectos individuales o grupales. Hay categorías por ciclo.', 'borrado', 'autor', true, now() - interval '498 hours', now() - interval '498 hours'),
  (30, (select id from public.boards where slug = 'eventos'), '00000000-0000-4000-8000-000000000009', 'sim_09', 'Maratón de programación escolar', 'Equipos de tres. Se resuelven problemas en 3 horas. Traer netbook.', 'publicado', null, true, now() - interval '1222 hours', now() - interval '1222 hours'),
  (31, (select id from public.boards where slug = 'eventos'), '00000000-0000-4000-8000-000000000008', 'sim_08', 'Jornada de limpieza del patio', 'Participan todos los cursos de la mañana. Traer guantes si tienen.', 'publicado', null, true, now() - interval '420 hours', now() - interval '420 hours'),
  (32, (select id from public.boards where slug = 'eventos'), '00000000-0000-4000-8000-000000000011', 'sim_11', 'Acto del aniversario de la escuela', 'Ensayo general el miércoles a la tarde. Participan 1° y 2° año.', 'publicado', null, true, now() - interval '393 hours', now() - interval '393 hours'),
  (33, (select id from public.boards where slug = 'eventos'), '00000000-0000-4000-8000-000000000010', 'sim_10', 'Visita a una planta industrial', 'Para 6° y 7° año. Hay que entregar la autorización firmada.', 'publicado', null, true, now() - interval '970 hours', now() - interval '970 hours'),
  (34, (select id from public.boards where slug = 'consultas'), '00000000-0000-4000-8000-000000000001', 'sim_01', '¿Cuándo se entregan los boletines?', '¿Alguien sabe la fecha? En preceptoría no me supieron decir.', 'publicado', null, true, now() - interval '117 hours', now() - interval '117 hours'),
  (35, (select id from public.boards where slug = 'consultas'), '00000000-0000-4000-8000-000000000012', 'sim_12', '¿Hay clases mañana?', 'Escuché que cortan la luz en la zona. ¿Confirmaron algo?', 'publicado', null, true, now() - interval '199 hours', now() - interval '199 hours'),
  (36, (select id from public.boards where slug = 'consultas'), '00000000-0000-4000-8000-000000000013', 'sim_13', 'Fechas de mesas de examen', '¿Dónde se publica el calendario de mesas de diciembre?', 'borrado', 'moderacion', true, now() - interval '699 hours', now() - interval '699 hours'),
  (37, (select id from public.boards where slug = 'consultas'), '00000000-0000-4000-8000-000000000001', 'sim_01', '¿Cómo pido un certificado de alumno regular?', 'Lo necesito para un trámite. ¿Se pide en secretaría o en preceptoría?', 'publicado', null, true, now() - interval '691 hours', now() - interval '691 hours'),
  (38, (select id from public.boards where slug = 'consultas'), '00000000-0000-4000-8000-000000000010', 'sim_10', 'Horario del buffet', '¿Hasta qué hora atiende el buffet en el turno tarde?', 'publicado', null, true, now() - interval '688 hours', now() - interval '688 hours'),
  (39, (select id from public.boards where slug = 'consultas'), '00000000-0000-4000-8000-000000000005', 'sim_05', 'Cambio de división: ¿se puede?', 'Mi división tiene el taller a contraturno y me complica. ¿Hay forma de cambiar?', 'publicado', null, true, now() - interval '870 hours', now() - interval '870 hours'),
  (40, (select id from public.boards where slug = 'consultas'), '00000000-0000-4000-8000-000000000016', 'sim_16', '¿Quién es el docente asesor de la cooperativa?', 'Quiero sumarme a la cooperativa y no sé con quién hablar.', 'borrado', 'moderacion', true, now() - interval '630 hours', now() - interval '630 hours'),
  (41, (select id from public.boards where slug = 'consultas'), '00000000-0000-4000-8000-000000000007', 'sim_07', 'Uso de celulares en clase', '¿Hay una regla general o cada profesor decide?', 'publicado', null, true, now() - interval '939 hours', now() - interval '939 hours');
